function renderMoneyLists(){const gl=jobs.filter(job=>job.source==='goline'),baseOutstanding=gl.filter(job=>job.status!=='Paid'&&['Completed','Submitted to GoLime'].includes(job.status)),outstanding=baseOutstanding.filter(job=>owedDateMatches(job)&&((owedStatusFilter==='outstanding')||(owedStatusFilter==='completed'&&job.status==='Completed')||(owedStatusFilter==='submitted'&&job.status==='Submitted to GoLime')||owedStatusFilter==='all')),paid=gl.filter(job=>job.status==='Paid'&&owedDateMatches(job)&&(owedStatusFilter==='paid'||owedStatusFilter==='all')),owed=golimeOwedSummary();document.querySelector('#outstandingAmount').textContent=money(owed.combinedTotal);document.querySelector('#owedStats').textContent=`${baseOutstanding.length} completed job${baseOutstanding.length===1?'':'s'} awaiting payment`;document.querySelector('#owedJobPay').textContent=money(owed.jobPay);document.querySelector('#owedExtrasPay').textContent=money(owed.extrasPay);document.querySelector('#owedTravelPay').textContent=money(owed.travelPayTotal);document.querySelector('#owedCombinedPay').textContent=money(owed.combinedTotal);document.querySelector('#outstandingJobs').innerHTML=outstanding.sort((a,b)=>b.date.localeCompare(a.date)).map(paymentJobRow).join('')||empty('No outstanding jobs match these filters.');document.querySelector('#paidJobs').innerHTML=paid.sort((a,b)=>b.date.localeCompare(a.date)).map(paymentJobRow).join('')||empty('No paid jobs match these filters.');}
