function reportTools(){return '<div style="position:sticky;top:0;z-index:5;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px;background:#fff;border-bottom:1px solid #dfe8ed"><div style="font:12px Arial;color:#315064"><b style="display:block;color:#0b2f4c">Ready for GoLime</b>Save this PDF, then attach it to the matching work order.</div><div style="display:flex;gap:8px"><button onclick="window.print()" style="border:0;border-radius:8px;background:#0c72b8;color:#fff;padding:9px 12px;font:700 13px Arial;cursor:pointer">Save GoLime PDF</button><button onclick="if(history.length>1){history.back()}else{window.close()}" style="border:1px solid #9fb5c3;border-radius:8px;background:#fff;color:#17334a;padding:9px 12px;font:700 13px Arial;cursor:pointer">Back to app</button></div></div>'}function legacyGenerateClaimPDF(){const data=claimData();if(!data.travel.length&&!data.extras.length){alert('There are no saved mileage records or extra charges in this claim period.');return}const label=`${new Date(data.start+'T12:00:00').toLocaleDateString('en-CA',{month:'long',day:'numeric'})}   ${new Date(data.end+'T12:00:00').toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'})}`,travelRows=data.travel.map(({date,record,calc})=>`<tr><td><strong>${esc(date)}</strong><br><small>Work orders: ${travelClaimWorkOrders(record)}</small><br><small>${esc(travelCalculationDescription(record))}</small></td><td>${Number(record.farthestKm).toFixed(1)} km</td><td>${calc.reimbursable.toFixed(1)} km</td><td>${money(calc.amount)}</td></tr>`).join('')||'<tr><td colspan="4">No saved travel records.</td></tr>',extraRows=data.extras.map(({job,extra})=>`<tr><td>${esc(job.date)}</td><td>${esc(job.workOrder||' ')}</td><td>${esc(extra.description||'Extra charge')}</td><td>${money(extra.amount)}</td></tr>`).join('')||'<tr><td colspan="4">No extra charges.</td></tr>',win=window.open('','_blank');win.document.write(`<!doctype html><html><head><base href="${location.origin}/"><title>GoLime Claim ${esc(data.start)} to ${esc(data.end)}</title><style>@page{size:A4;margin:12mm}body{font-family:Arial,sans-serif;color:#152431;margin:0}header{border-bottom:3px solid #0c72b8;padding-bottom:14px;margin-bottom:20px}h1{margin:0;color:#0b2f4c;font-size:25px}header p{margin:5px 0 0;color:#60717d;font-size:12px}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:16px 0 26px}.summary div{background:#eef7fc;padding:12px;border-radius:8px}.summary span{display:block;font-size:10px;color:#60717d;text-transform:uppercase;font-weight:bold}.summary strong{display:block;font-size:19px;margin-top:4px;color:#0b2f4c}h2{font-size:16px;color:#0b2f4c;margin:24px 0 8px}table{width:100%;border-collapse:collapse;font-size:11px}th{text-align:left;background:#0b2f4c;color:#fff;padding:9px}td{padding:9px;border-bottom:1px solid #dfe8ed}td:last-child,th:last-child{text-align:right;font-weight:bold}.total{font-size:18px;font-weight:bold;text-align:right;margin-top:14px;color:#0b2f4c}.note{font-size:10px;color:#60717d;margin-top:24px}</style></head><body>${reportTools()}<header><div style="display:flex;align-items:center;gap:12px"><img src="akon-air-mark.png" alt="Akon Air" style="width:130px;height:43px;object-fit:contain;background:#07517f;border-radius:7px;padding:2px"><img src="goline-logo.jpg" alt="GoLime" style="width:50px;height:43px;object-fit:contain"><h1>Akon Air   GoLime Claim</h1></div><p>${esc(label)}   Warehouse: ${esc(travelWarehouse)}</p></header><div class="summary"><div><span>Travel pay</span><strong>${money(data.travelTotal)}</strong></div><div><span>Extra charges</span><strong>${money(data.extrasTotal)}</strong></div><div><span>Total claim</span><strong>${money(data.travelTotal+data.extrasTotal)}</strong></div></div><h2>Travel reimbursement</h2><table><thead><tr><th>Date</th><th>Farthest job</th><th>Chargeable detour</th><th>Travel pay</th></tr></thead><tbody>${travelRows}</tbody></table><h2>Extra charges</h2><table><thead><tr><th>Date</th><th>Work order</th><th>Description</th><th>Amount</th></tr></thead><tbody>${extraRows}</tbody></table><p class="total">Claim total: ${money(data.travelTotal+data.extrasTotal)}</p><p class="note">Travel calculation: route across the day s jobs minus the warehouse-to-farthest-job route. Detours over 18 km are charged in full at $0.75/km.</p></body></html>`);win.document.close();}
function travelClaimWorkOrders(record){const items=(record.routes||[]).map(route=>({route,job:jobs.find(job=>job.id===route.jobId)})).filter(item=>item.job?.workOrder);if(!items.length)return 'No linked work orders';const farthest=items.reduce((best,item)=>Number(item.route.km||0)>Number(best.route.km||0)?item:best,items[0]);return items.map(item=>`${esc(item.job.workOrder)}${item===farthest?' (farthest)':''}`).join(', ')}function generateClaimPDF(){const data=claimData();if(!data.travel.length&&!data.extras.length){alert('There are no saved mileage records or extra charges in this claim period.');return}const label=`${new Date(data.start+'T12:00:00').toLocaleDateString('en-CA',{month:'long',day:'numeric'})} to ${new Date(data.end+'T12:00:00').toLocaleDateString('en-CA',{month:'long',day:'numeric',year:'numeric'})}`,travelRows=data.travel.map(({date,record,calc})=>`<tr><td><strong>${esc(date)}</strong><br><small>Work orders: ${travelClaimWorkOrders(record)}</small><br><small>${esc(travelCalculationDescription(record))}</small></td><td>${Number(record.farthestKm).toFixed(1)} km</td><td>${calc.reimbursable.toFixed(1)} km</td><td>${money(calc.amount)}</td></tr>`).join('')||'<tr><td colspan="4">No saved travel records.</td></tr>',extraRows=data.extras.map(({job,extra})=>`<tr><td>${esc(job.date)}</td><td>${esc(job.workOrder||'-')}</td><td>${esc(extra.description||'Extra charge')}</td><td>${money(extra.amount)}</td></tr>`).join('')||'<tr><td colspan="4">No extra charges.</td></tr>',win=window.open('','_blank');if(!win){alert('Please allow pop-ups to open the report.');return}win.document.write(`<!doctype html><html><head><base href="${location.origin}/"><title>GoLime Claim ${esc(data.start)} to ${esc(data.end)}</title><style>@page{size:A4;margin:12mm}body{font-family:Arial,sans-serif;color:#152431;margin:0}header{border-bottom:3px solid #0c72b8;padding-bottom:14px;margin-bottom:20px}h1{margin:0;color:#0b2f4c;font-size:25px}header p{margin:5px 0 0;color:#60717d;font-size:12px}.summary{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:16px 0 26px}.summary div{background:#eef7fc;padding:12px;border-radius:8px}.summary div.total{background:#eaf7ef}.summary span{display:block;font-size:10px;color:#60717d;text-transform:uppercase;font-weight:bold}.summary strong{display:block;font-size:19px;margin-top:4px;color:#0b2f4c}h2{font-size:16px;color:#0b2f4c;margin:24px 0 8px}table{width:100%;border-collapse:collapse;font-size:11px}th{text-align:left;background:#0b2f4c;color:#fff;padding:9px}td{padding:9px;border-bottom:1px solid #dfe8ed}td:last-child,th:last-child{text-align:right;font-weight:bold}.final-total{font-size:18px;font-weight:bold;text-align:right;margin-top:14px;color:#0b2f4c}.note{font-size:10px;color:#60717d;margin-top:24px}</style></head><body>${reportTools()}<header><div style="display:flex;align-items:center;gap:12px"><img src="akon-air-mark.png" alt="Akon Air" style="width:130px;height:43px;object-fit:contain;background:#07517f;border-radius:7px;padding:2px"><img src="goline-logo.jpg" alt="GoLime" style="width:50px;height:43px;object-fit:contain"><h1>Akon Air - GoLime Claim</h1></div><p>${esc(label)} - Warehouse: ${esc(travelWarehouse)}</p></header><div class="summary"><div><span>Travel pay</span><strong>${money(data.travelTotal)}</strong></div><div><span>Extra charges</span><strong>${money(data.extrasTotal)}</strong></div><div><span>HST (13%)</span><strong>${money(data.hst)}</strong></div><div class="total"><span>Total claim incl. HST</span><strong>${money(data.totalWithHst)}</strong></div></div><h2>Travel reimbursement</h2><table><thead><tr><th>Date</th><th>Farthest job</th><th>Chargeable detour</th><th>Travel pay</th></tr></thead><tbody>${travelRows}</tbody></table><h2>Extra charges</h2><table><thead><tr><th>Date</th><th>Work order</th><th>Description</th><th>Amount</th></tr></thead><tbody>${extraRows}</tbody></table><p class="final-total">Claim total including HST: ${money(data.totalWithHst)}</p><p class="note">Travel calculation: route across the day s jobs minus the warehouse-to-farthest-job route. Detours over 18 km are charged in full at $0.75/km.</p></body></html>`);win.document.close()}
async function geocodeAddress(address){const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=ca&q=${encodeURIComponent(address)}`);if(!response.ok)throw new Error('Address lookup failed');const result=await response.json();if(!result[0])throw new Error('Address not found');return {lat:Number(result[0].lat),lon:Number(result[0].lon)}}
async function routeDistanceKm(from,to){const response=await fetch(`https://router.project-osrm.org/route/v1/driving/${from.lon},${from.lat};${to.lon},${to.lat}?overview=false`);if(!response.ok)throw new Error('Route lookup failed');const result=await response.json();if(!result.routes?.[0])throw new Error('No driving route');return result.routes[0].distance/1000}
async function calculateTravelRecord(date,warehouse){const dayJobs=jobs.filter(job=>job.source==='goline'&&job.date===date).sort(scheduleOrder);if(!dayJobs.length)throw new Error('No GoLime jobs are scheduled for this date.');const origin=await geocodeAddress(warehouse),routes=[],mapped=[];for(const job of dayJobs){if(!job.address){routes.push({jobId:job.id,error:'No address'});continue}try{const destination=await geocodeAddress(job.address),directKm=await routeDistanceKm(origin,destination);mapped.push({job,destination,directKm});routes.push({jobId:job.id,km:directKm})}catch(error){routes.push({jobId:job.id,error:'Could not map'})}}if(!mapped.length)throw new Error('No job addresses could be mapped.');let previous=origin,totalRouteKm=0;for(const item of mapped){const legKm=await routeDistanceKm(previous,item.destination),route=routes.find(row=>row.jobId===item.job.id);if(route)route.legKm=legKm;totalRouteKm+=legKm;previous=item.destination}const farthest=Math.max(...mapped.map(item=>item.directKm)),detourKm=Math.max(0,totalRouteKm-farthest);return {warehouse,routes,farthestKm:farthest,totalRouteKm,detourKm,manual:false,calculationVersion:'detour-v1',updatedAt:new Date().toISOString()}}
async function calculateTravel(){const warehouse=document.querySelector('#warehouseAddress').value.trim(),status=document.querySelector('#travelStatus'),button=document.querySelector('[data-action="calculate-travel"]');if(!warehouse){status.textContent='Enter the GoLime warehouse address first.';return}travelWarehouse=warehouse;localStorage.setItem('akon-air-warehouse',travelWarehouse);button.disabled=true;status.textContent='Measuring the route across today s GoLime jobs...';try{travelData[travelDate]=await calculateTravelRecord(travelDate,warehouse);saveTravel();status.textContent='Travel route calculated using the 18 km detour allowance.';renderTravelDetails()}catch(error){status.textContent=error.message||'Could not calculate driving routes. Check the job addresses or use the manual distance fallback.';console.error('Travel calculation failed:',error)}finally{button.disabled=false}}
async function recalculateSavedTravel(){const status=document.querySelector('#travelStatus'),button=document.querySelector('[data-action="recalculate-travel"]'),entries=Object.entries(travelData).filter(([,record])=>record?.farthestKm!==undefined);if(!entries.length){status.textContent='There are no saved travel records to recalculate.';return}if(button)button.disabled=true;let updated=0;try{for(const [date,record] of entries){status.textContent='Recalculating '+(updated+1)+' of '+entries.length+' saved travel days...';try{travelData[date]=await calculateTravelRecord(date,record.warehouse||travelWarehouse);updated++}catch(error){console.warn('Could not recalculate travel date',date,error)}}saveTravel();status.textContent='Recalculated '+updated+' saved travel day'+(updated===1?'':'s')+' using the 18 km detour rule.';renderTravelDetails()}finally{if(button)button.disabled=false}}
const saveTravelFailures=()=>localStorage.setItem('akon-air-travel-failures',JSON.stringify(travelCalculationFailures));const travelJobSignature=date=>jobs.filter(job=>job.source==='goline'&&job.date===date).sort(scheduleOrder).map(job=>[job.id,job.address,job.appointmentStart,job.appointmentEnd].join('|')).join('||');async function automaticallyCalculateTravel(dates,force=false){if(autoTravelBusy||!navigator.onLine)return;const targetDates=[...new Set(dates)].filter(date=>jobs.some(job=>job.source==='goline'&&job.date===date));if(!targetDates.length)return;autoTravelBusy=true;let changed=false;try{for(const date of targetDates){const record=travelData[date],signature=travelJobSignature(date);if(record?.manual||(!force&&record?.calculationVersion==='detour-v1'&&record?.travelSignature===signature))continue;try{const calculated=await calculateTravelRecord(date,record?.warehouse||travelWarehouse);calculated.travelSignature=signature;travelData[date]=calculated;delete travelCalculationFailures[date];changed=true}catch(error){travelCalculationFailures[date]=error.message||'Travel could not be calculated. Check the job address.';saveTravelFailures()}}if(changed){saveTravel();saveTravelFailures();if(currentView==='dashboard')render('dashboard')}}finally{autoTravelBusy=false}}
function applyManualTravel(){const km=Number(document.querySelector('#manualTravelKm').value),status=document.querySelector('#travelStatus');if(!Number.isFinite(km)||km<0){status.textContent='Enter a valid one-way distance in kilometres.';return}travelWarehouse=document.querySelector('#warehouseAddress').value.trim()||travelWarehouse;localStorage.setItem('akon-air-warehouse',travelWarehouse);travelData[travelDate]={warehouse:travelWarehouse,routes:travelData[travelDate]?.routes||[],farthestKm:km,totalRouteKm:km,detourKm:0,manual:true,calculationVersion:'detour-v1',updatedAt:new Date().toISOString()};saveTravel();status.textContent='Manual farthest-job distance applied. Add a mapped route to calculate any detour.';renderTravelDetails()}function calendarView(){app.append(template('calendar-template'));drawCalendar();}
