// Every printable document must lead with the registered legal company name.
// This wrapper applies the same legal masthead to completion reports, claims,
// travel reimbursement, and extra-charge PDFs without changing any job data.
const nativeReportWindowOpen=window.open.bind(window);
window.open=(...args)=>{
  const reportWindow=nativeReportWindowOpen(...args);
  if(!reportWindow?.document)return reportWindow;
  const nativeWrite=reportWindow.document.write.bind(reportWindow.document);
  reportWindow.document.write=markup=>{
    let documentHtml=String(markup);
    const legalHeading=`<div class="legal-document-company"><h1>${LEGAL_COMPANY_NAME}</h1><p>${OPERATING_BRAND}</p><small>GoLime field document</small></div>`;
    documentHtml=documentHtml
      .replace(/<h1>Akon Air\s*(?:-|\s+)\s*GoLime Claim<\/h1>/g,legalHeading)
      .replace(/<div><b>AKON AIR<\/b><small>GOLIME COMPLETION REPORT<\/small><\/div>/g,`<div class="legal-document-company"><b>${LEGAL_COMPANY_NAME}</b><small>${OPERATING_BRAND} · GoLime Completion Report</small></div>`)
      .replace(/Akon Air Field Management/g,`${LEGAL_COMPANY_NAME} · ${OPERATING_BRAND}`)
      .replace(/<title>([^<]*(?:Completion Report|GoLime Claim)[^<]*)<\/title>/g,`<title>${LEGAL_COMPANY_NAME} — $1</title>`)
      .replace('</style>','.legal-document-company h1{font-size:22px!important;letter-spacing:.3px}.legal-document-company p{margin:3px 0 0;font-weight:700}.legal-document-company small{display:block;margin-top:2px}</style>');
    return nativeWrite(documentHtml);
  };
  return reportWindow;
};

// Cloud polling should keep data current without tearing down the interactive
// Home map every few seconds.  Home stays visually stable; fresh data is kept
// in memory and appears the next time Home is opened.
refreshFromCloud=async()=>{
  if(!remoteReady||cloudPushPromise)return;
  try{
    const before=routeMapSnapshot(),latest=await loadCloudData();
    jobs=mergeJobsForSync(jobs,latest.jobs);
    travelData={...latest.travel,...travelData};
    if(pendingCloudSync&&navigator.onLine)scheduleCloudSync();
    const changed=before!==routeMapSnapshot();
    if(changed&&currentView!=='dashboard'&&['jobs','money','travel','extras','claims','calendar','detail','files'].includes(currentView))render(currentView);
    if(currentView==='dashboard')updateHeader();
    updateSharedSyncStatus();
  }catch(error){console.error('Shared refresh failed:',error)}
};

// Do not replace a visible Leaflet map with a loading message while the user
// is looking at Home.  A new map is created only when the Home screen itself
// is opened again.
const renderRouteMapWithoutFlicker=renderTodayRouteMap;
let homeRouteMapRendering=false;
renderTodayRouteMap=async()=>{
  const container=document.querySelector('#todayRouteMap');
  if(!container||homeRouteMapRendering)return;
  if(homeStreetMap&&container.querySelector('#todayStreetMap'))return;
  homeRouteMapRendering=true;
  try{await renderRouteMapWithoutFlicker()}finally{homeRouteMapRendering=false}
};

